let
    // ---- SOURCE ----
    Source = Excel.CurrentWorkbook(){[Name="tblResponses"]}[Content],

    // Add a stable response id
    AddResponseID = Table.AddIndexColumn(Source, "ResponseID", 1, 1, Int64.Type),

    // Ensure Name column exists (if not, create blank)
    EnsureName =
        if List.Contains(Table.ColumnNames(AddResponseID), "Name")
        then AddResponseID
        else Table.AddColumn(AddResponseID, "Name", each null, type text),

    ColNames = Table.ColumnNames(EnsureName),
    F3Cols = List.Select(ColNames, each Text.StartsWith(_, "F3-")),

    KeepCols = List.Combine({{"ResponseID","Name"}, F3Cols}),
    SelectF3 = Table.SelectColumns(EnsureName, KeepCols, MissingField.UseNull),

    // Unpivot F3 columns
    Unpivoted = Table.UnpivotOtherColumns(SelectF3, {"ResponseID","Name"}, "Attribute", "Value"),

    // CandidateID is always first 5 chars like F3-01
    AddCandidateID = Table.AddColumn(Unpivoted, "CandidateID", each Text.Start([Attribute], 5), type text),

    // Classify field type based on attribute name
    AddFieldType = Table.AddColumn(
        AddCandidateID,
        "FieldType",
        each
            if Text.Contains([Attribute], " approval") then "Approval"
            else if Text.Contains([Attribute], " proposed revision") then "ProposedRevision"
            else if Text.Contains([Attribute], " TR codes") then "TR"
            else if Text.Contains([Attribute], " comment") then "Comment"
            else "Other",
        type text
    ),

    FilterKnown = Table.SelectRows(AddFieldType, each [FieldType] <> "Other"),

    // Pivot FieldType into columns
    Pivoted = Table.Pivot(
        FilterKnown,
        List.Distinct(FilterKnown[FieldType]),
        "FieldType",
        "Value",
        each List.First(_)
    ),

    // Ensure expected columns exist
    EnsureApproval =
        if List.Contains(Table.ColumnNames(Pivoted), "Approval")
        then Pivoted
        else Table.AddColumn(Pivoted, "Approval", each null, type text),

    EnsureRevision =
        if List.Contains(Table.ColumnNames(EnsureApproval), "ProposedRevision")
        then EnsureApproval
        else Table.AddColumn(EnsureApproval, "ProposedRevision", each null, type text),

    EnsureTR =
        if List.Contains(Table.ColumnNames(EnsureRevision), "TR")
        then EnsureRevision
        else Table.AddColumn(EnsureRevision, "TR", each null, type text),

    EnsureComment =
        if List.Contains(Table.ColumnNames(EnsureTR), "Comment")
        then EnsureTR
        else Table.AddColumn(EnsureTR, "Comment", each null, type text),

    // Split TR codes into rows (semicolon-separated in Forms export)
    AddTRList = Table.AddColumn(
        EnsureComment,
        "TR_List",
        each
            let
                raw = if [TR] = null then "" else Text.Trim(Text.From([TR])),
                list =
                    if raw = ""
                    then { null }
                    else List.Transform(Text.Split(raw, ";"), each Text.Trim(_))
            in
                list,
        type list
    ),
    ExpandTR = Table.ExpandListColumn(AddTRList, "TR_List"),
    RenameTR = Table.RenameColumns(ExpandTR, {{"TR_List", "TR"}}),

    // HasComment flag
    AddHasComment = Table.AddColumn(
        RenameTR,
        "HasComment",
        each if [Comment] <> null and Text.Trim(Text.From([Comment])) <> "" then 1 else 0,
        Int64.Type
    )
in
    AddHasComment
